parameter_expressions:
{"path":""/app/rest/projects"","locator":"[
        options.parent
          ? nestedId("project", options.parent, "TeamCity parent project ID")
          : undefined,
        options.includeArchived === true ? undefined : "archived:false",
      ]","key":""project"","fields":"projectFields","project":"(item) => item as TeamCityProject","page":"options"}

{"path":""/app/rest/buildTypes"","locator":"[
        "templateFlag:false",
        options.project ? nestedId("project", options.project, "TeamCity project ID") : undefined,
      ]","key":""buildType"","fields":"jobFields","project":"(item) => item as TeamCityJob","page":"options"}

{"method":""GET"","path":""/app/rest/builds"","query":"{
      locator: joinLocator(
        "defaultFilter:false",
        nestedId("buildType", job, "TeamCity job ID"),
        branchDimension(branch),
        "state:finished",
        "personal:false",
        "count:1",
      ),
      fields: `build(${buildFields})`,
    }","body":"<omitted>"}

{"path":""/app/rest/testOccurrences"","locator":"[
        `build:(id:${positiveId(id, "TeamCity build ID")})`,
        options.status ? `status:${options.status}` : undefined,
      ]","key":""testOccurrence"","fields":"testOccurrenceFields","project":"(item) => item as TeamCityTestOccurrence","page":"options"}

{"path":""/app/rest/changes"","locator":"[`build:(id:${positiveId(id, "TeamCity build ID")})`]","key":""change"","fields":"changeFields","project":"(item) => {
        const change = item as RawTeamCityChange;
        return {
          id: change.id,
          version: change.version,
          date: change.date,
          ...(change.internalVersion === undefined
            ? {}
            : { internalVersion: change.internalVersion }),
          ...(change.commitDate === undefined ? {} : { commitDate: change.commitDate }),
          ...(change.comment === undefined ? {} : { comment: change.comment }),
          ...(change.webUrl === undefined ? {} : { webUrl: change.webUrl }),
          ...(change.commiter?.vcsUsername === undefined
            ? {}
            : { committer: change.commiter.vcsUsername }),
        };
      }","page":"options"}

{"path":""/app/rest/buildQueue"","locator":"[
        options.job ? nestedId("buildType", options.job, "TeamCity job ID") : undefined,
        options.project ? nestedId("project", options.project, "TeamCity project ID") : undefined,
      ]","key":""build"","fields":"buildFields","project":"(item) => item as TeamCityBuild","page":"options"}

{"method":""POST"","path":""/app/rest/buildQueue"","query":"{ fields: buildFields }","body":"{
          buildType: { id: jobId },
          ...(options.cleanSources === undefined
            ? {}
            : { triggeringOptions: { cleanSources: options.cleanSources } }),
          ...(options.branch === undefined
            ? {}
            : { branchName: requiredText(options.branch, "TeamCity branch name") }),
          ...(options.comment === undefined
            ? {}
            : { comment: { text: requiredText(options.comment, "Build comment") } }),
          ...(options.properties === undefined || options.properties.length === 0
            ? {}
            : {
                properties: {
                  property: options.properties.map(({ name, value }) => ({ name, value })),
                },
              }),
        }","mediaType":"<omitted>","responseOptions":"<omitted>"}

{"method":""POST"","path":""/app/rest/projects"","query":"{ fields: projectFields }","body":"{
        id: requiredText(id, "Project ID"),
        name: requiredText(options.name, "Project name"),
        parentProject: { id: requiredText(options.parent ?? "_Root", "Parent project ID") },
        ...(options.description === undefined ? {} : { description: options.description }),
      }"}

{"method":""POST"","path":""/app/rest/buildTypes"","query":"{ fields: jobFields }","body":"{
        id: requiredText(id, "Job ID"),
        name: requiredText(options.name, "Job name"),
        project: { id: requiredText(options.project, "Project ID") },
        ...(options.description === undefined ? {} : { description: options.description }),
      }"}

{"method":""POST"","path":"`${projectPath(options.project)}/buildTypes`","query":"{ fields: "id,name,projectId" }","body":"{
        id: requiredText(id, "Job ID"), name: requiredText(options.name, "Job name"),
        sourceBuildType: { id: requiredText(source, "Source job ID") },
        copyAllAssociatedSettings: true,
      }"}

{"path":"`${jobPath(jobId)}/branches`","locator":"[]","key":""branch"","fields":""name,default,active"","project":"(item) => {
      const { name, default: isDefault, active } =
        item as { name: string; default?: boolean; active?: boolean };
      return {
        name,
        ...(isDefault === undefined ? {} : { default: isDefault }),
        ...(active === undefined ? {} : { active }),
      };
    }","page":"options"}

{"path":"`${projectPath(projectId)}/branches`","locator":"[]","key":""branch"","fields":""name,default"","project":"(item) => {
      const branch = item as { name: string; default?: boolean };
      return {
        name: branch.name,
        ...(branch.default === undefined ? {} : { default: branch.default }),
      };
    }","page":"options"}

{"method":""GET"","path":"admin.accountPath("users", id) + "/permissions"","query":"{
        ...(project === undefined ? {} : { locator: nestedId("project", project, "Project ID") }),
        fields: "count,permissionAssignment(permission(id),project(id),isGlobalScope)",
      }","body":"<omitted>"}

{"path":""/app/rest/cloud/" + kind","locator":"[
        project === undefined ? undefined : nestedId("project", project, "Project ID"),
        profile === undefined ? undefined : nestedId("profile", profile, "Cloud profile ID"),
      ]","key":"infrastructure.cloudCollection[kind]","fields":"infrastructure.cloudFields[kind]","project":"(item) => infrastructure.safeCloud(item, kind)","page":"page"}

{"method":""POST"","path":"path","query":"{ fields: buildFields }","body":"{
        ...(options.comment === undefined
          ? {}
          : { comment: requiredText(options.comment, "Cancellation comment") }),
        readdIntoQueue: false,
      }"}

{"method":""GET"","path":"path","query":"{
        locator: joinLocator(
          ...locator,
          `start:${request.start}`,
          `count:${request.count}`,
          request.lookupLimit === undefined ? undefined : `lookupLimit:${request.lookupLimit}`,
        ),
        fields: `nextHref,${key}(${fields})`,
      }","body":"<omitted>"}

{"method":""POST"","path":""/app/rest/deploymentDashboards"","query":"{}","body":"{
          id: triage.inputText(id, "Dashboard ID"),
          name: triage.inputText(name, "Name"),
          project: { id: triage.inputText(project, "Project ID") },
        }"}

{"method":""POST"","path":"system.dashboardPath(dashboard) + "/instances"","query":"{}","body":"{
          id: triage.inputText(id, "Instance ID"),
          attributes: {},
          deploymentStateEntries: { deploymentStateEntry: [entry] },
        }"}

{"method":""POST"","path":""/app/rest/roles"","query":"{ fields: system.roleFields }","body":"{
          name: triage.inputText(name, "Name"),
          permissions: { permission: system.idsOrEmpty(permissions).map((id) => ({ id })) },
          included: { role: system.idsOrEmpty(included).map((id) => ({ id })) },
        }"}

{"method":""POST"","path":""/app/rest/server/backup"","query":"{
        fileName: name,
        addTimestamp: "true",
        includeConfigs: "true",
        includeDatabase: "true",
        includeBuildLogs: "false",
        includePersonalChanges: "false",
        includeRunningBuilds: "false",
        includeSupplimentaryData: "false",
      }","body":"undefined","mediaType":""text/plain"","responseOptions":"<omitted>"}
